import sys, time
sys.path.insert(0, "/home/claude")
import usb.core, usb.util
from repro_getvar import recover, fastbootd_present, log, BASE, run
def boot_reason():
    for _ in range(40):
        o,_ = run(["adb","devices"],10)
        if "GUSA2427018764\tdevice" in o:
            r,_ = run(["adb","shell","getprop","sys.boot.reason"],20); return r.strip()
        time.sleep(3)
    return "unknown"
def open_dev():
    d = usb.core.find(idVendor=0x18d1, idProduct=0x4ee0)
    usb.util.claim_interface(d, 0)
    return d
if not fastbootd_present():
    print("not in fastbootd"); sys.exit(1)
dev = open_dev()
for trial in range(5):
    for i in range(3):
        try:
            dev.write(0x01, b"A"*255, timeout=500)
        except Exception as e:
            print("trial", trial, "write", i, "error", e)
    time.sleep(3)
    alive = fastbootd_present()
    print(f"trial {trial+1}: 3x255 sent, alive={alive}", flush=True)
    if not alive:
        print("  boot reason:", boot_reason(), flush=True)
        if not recover():
            print("did not recover"); break
        dev = open_dev()
EOF

